effect.shader:
const float PI = 3.14159265;
const float TAU = 6.28318530;

vec4 fatiar(vec2 uv, float jitter) {
    vec2 p = uv - center;
    p.x *= acAspect;
    float r = length(p);
    float ang = atan(p.y, p.x) - rotation * PI / 180.0 + jitter;

    float setor = TAU / max(float(slices), 1.0);
    ang = mod(ang, setor);
    if (ang > setor * 0.5) ang = setor - ang;

    vec2 q = vec2(cos(ang), sin(ang)) * (r / max(zoom, 0.01));
    q.x /= acAspect;
    return texture(inputImg, q + center);
}

void main() {
    if (softness <= 0.0) {
        fragColor = fatiar(acScreenNorm, 0.0);
        return;
    }

    const int N = 5;
    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        float jitter = (float(i) / float(N - 1) - 0.5) * softness * TAU;
        soma += fatiar(acScreenNorm, jitter);
    }
    fragColor = soma / float(N);
}
